import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, sin } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Euler } = ctx.THREE;

  const root = new Group();
  root.name = 'pricing-title';

  const timelines = [];
  const loadedTextures = [];
  let alive = true;

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const stageMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: true,
  });

  const stageUv = uv();
  const gradientT = smoothstep(0.0, 1.0, stageUv.y);
  const surface = vec3(0.043, 0.043, 0.063);
  const ink = vec3(0.086, 0.086, 0.114);
  const gradient = mix(surface, ink, gradientT);
  const grainValue = sin(
    stageUv.x.mul(173.0).add(stageUv.y.mul(311.0))
  ).mul(0.008);
  stageMaterial.colorNode = gradient.add(
    vec3(grainValue, grainValue, grainValue)
  );

  const stage = new Mesh(new PlaneGeometry(7, 6), stageMaterial);
  stage.name = 'engineered-gradient-stage';
  stage.position.set(0, 0, -2.5);
  root.add(stage);

  const frameMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.92,
    depthWrite: false,
  });

  const frame = new Mesh(new PlaneGeometry(3.15, 0.018), frameMaterial);
  frame.name = 'signal-red-rule';
  frame.position.set(0, -0.72, -1.9);
  root.add(frame);

  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.5,
    depthWrite: false,
  });

  const surfacePanel = new Mesh(
    new PlaneGeometry(5.8, 1.65),
    surfaceMaterial
  );
  surfacePanel.name = 'ink-title-panel';
  surfacePanel.position.set(0, 0.05, -2.18);
  root.add(surfacePanel);

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  for (const item of items) {
    const content = typeof item.text === 'string' ? item.text : '';
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? 96,
      color: colors.paper,
      align: 'center',
    });

    textObject.name = item.role || 'headline';
    textObject.position.set(0, -0.18, -1.65);
    root.add(textObject);
  }

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((texture) => {
        if (!alive) {
          texture.dispose?.();
          return;
        }

        loadedTextures.push(texture);

        const imageMaterial = new MeshBasicNodeMaterial({
          color: colors.paper,
          transparent: true,
          opacity: 0.055,
          depthWrite: false,
        });

        imageMaterial.map = texture;
        imageMaterial.needsUpdate = true;

        const imagePlane = new Mesh(
          new PlaneGeometry(5.1, 2.65),
          imageMaterial
        );
        imagePlane.name = 'isolated-atelier-image';
        imagePlane.position.set(0, 0.12, -1.95);
        root.add(imagePlane);
      })
      .catch(() => {});
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    alive = false;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }
    timelines.length = 0;

    const disposedMaterials = new Set();
    const disposedGeometries = new Set();

    root.traverse((object) => {
      if (object.geometry && !disposedGeometries.has(object.geometry)) {
        disposedGeometries.add(object.geometry);
        object.geometry.dispose?.();
      }

      const material = object.material;
      if (material && !disposedMaterials.has(material)) {
        disposedMaterials.add(material);
        material.dispose?.();
      }
    });

    for (const texture of loadedTextures) {
      texture.dispose?.();
    }
    loadedTextures.length = 0;
  };

  return root;
}
